set -a; . /var/www/viamood/.env.production; set +a
mkdir -p /tmp/g994771/basim-once
echo  | base64 -d > /tmp/g994771/yama.py
echo  | base64 -d > /tmp/g994771/md5.json
cd /tmp/g994771 && python3 - <<"PYEOF"
import json,urllib.request,urllib.parse,os,hashlib,time,sys
sys.path.insert(0,"/tmp/g994771"); import yama
T=os.environ["SHOPIFY_ADMIN_ACCESS_TOKEN"]; D=os.environ["SHOPIFY_STORE_DOMAIN"]; V=os.environ["SHOPIFY_API_VERSION"]
TEMA="195348856964"; M=json.load(open("/tmp/g994771/md5.json"))
md5=lambda s: hashlib.md5(s.encode()).hexdigest()
def get(k):
    u=f"https://{D}/admin/api/{V}/themes/{TEMA}/assets.json?asset%5Bkey%5D={urllib.parse.quote(k)}"
    return json.load(urllib.request.urlopen(urllib.request.Request(u,headers={"X-Shopify-Access-Token":T}),timeout=60))["asset"]["value"]
def put(k,v):
    body=json.dumps({"asset":{"key":k,"value":v}}).encode()
    r=urllib.request.urlopen(urllib.request.Request(f"https://{D}/admin/api/{V}/themes/{TEMA}/assets.json",data=body,method="PUT",headers={"X-Shopify-Access-Token":T,"Content-Type":"application/json"}),timeout=90)
    return r.status
SIRA=["assets/base.css","assets/empire-overrides.css","assets/via-mobile-app.css","assets/via-product-overrides.css","snippets/quantity-selector.liquid","snippets/sku.liquid","snippets/predictive-search-products-list.liquid","snippets/predictive-search-styles.liquid","snippets/via-kargo-sayaci.liquid","templates/product.json"]
assert set(SIRA)==set(M), "liste uyusmuyor"
# 1) ON KAPI: canli == yedek (md5) — biri bile farkliysa HIC basilmaz
once={}; yeni={}
for k in SIRA:
    v=get(k); once[k]=v; time.sleep(0.5)
    h=md5(v)
    if h==M[k]["sonra"][1]:
        print("ZATEN-BASILI",k,h); yeni[k]=None; continue
    ok=(h==M[k]["once"][1]); print("CANLI-ONCE",k,len(v.encode()),h,"=YEDEK" if ok else "!!FARKLI(yedek "+M[k]["once"][1]+")")
    if not ok: print("DUR: canli yedekle ayni degil, basim YAPILMADI"); sys.exit(0)
    open("/tmp/g994771/basim-once/"+k.replace("/","__"),"w").write(v)
    y=yama.uygula(k,v)
    if md5(y)!=M[k]["sonra"][1]: print("DUR: sunucuda uretilen yama md5",md5(y),"!= yerel",M[k]["sonra"][1]); sys.exit(0)
    yeni[k]=y
print("ON-KAPI: tum dosyalar canli=yedek ya da zaten basili; yama md5=yerel SONRASI")
for k in SIRA:
    b=open("/tmp/g994771/basim-once/"+k.replace("/","__")).read()
    if md5(b)!=M[k]["once"][1]: print("DUR: geri alma kopyasi yedekle ayni degil",k); sys.exit(0)
print("GERI-ALMA-KOPYALARI: 10/10 sunucuda, md5=yedek")
# 2) BASIM + GET-back; dusen olursa basilanlari geri al
basilan=[]; hata=None
for k in SIRA:
    if yeni[k] is None:
        g=md5(get(k)); ok=(g==M[k]["sonra"][1]); print("ATLA(zaten basili)",k,"GET-BACK",g,"OK" if ok else "!!UYUSMADI")
        if not ok: hata=k+" zaten-basili dogrulanamadi"; break
        basilan.append(k); continue
    try:
        st=put(k,yeni[k]); basilan.append(k)
        # okuma-yazma gecikmesi OLCULDU (16:07): 1.2 sn'de eski icerik dondu, 2.6 sn'de yeni => 20 sn'ye kadar yokla
        for _ in range(10):
            time.sleep(2); g=md5(get(k))
            if g==M[k]["sonra"][1]: break
        ok=(g==M[k]["sonra"][1]); print("PUT",k,st,"GET-BACK",len(yeni[k].encode()),g,"OK" if ok else "!!UYUSMADI")
        if not ok: hata=k+" get-back uyusmadi"; break
    except Exception as e:
        hata=k+" "+repr(e)[:200]; print("HATA",hata); break
    time.sleep(0.6)
if hata:
    print("GERI-ALMA BASLADI:",hata)
    for k in basilan:
        try:
            put(k,open("/tmp/g994771/basim-once/"+k.replace("/","__")).read())
            for _ in range(10):
                time.sleep(2); g=md5(get(k))
                if g==M[k]["once"][1]: break
            print("GERI",k,g,"=YEDEK" if g==M[k]["once"][1] else "!!")
        except Exception as e: print("GERI-HATA",k,repr(e)[:200])
else:
    print("BASIM-TAMAM",time.strftime("%H:%M:%S"))
PYEOF
